        m = len(andValues)
        INF = float('inf')
        # states[k]: dict and_value -> min cost, where segment k is open
        states = [dict() for _ in range(m)]
        # start segment 0 at nums[0]
        states[0][nums[0]] = 0
        for i in range(1, n):
            x = nums[i]
            prev = nums[i-1]
            nd = [dict() for _ in range(m)]
            for k in range(m):
                for a, c in states[k].items():
                    na = a & x
                    if na >= andValues[k]:
                        if nd[k].get(na, INF) > c:
                            nd[k][na] = c
            for k in range(m):
                for a, c in states[k].items():
                    if a == andValues[k] and k + 1 < m:
                        nc = c + prev
                        if nd[k+1].get(x, INF) > nc:
                            nd[k+1][x] = nc
            states = nd
        best = INF
        for a, c in states[m-1].items():
            if a == andValues[m-1]:
                best = min(best, c + nums[n-1])
        return -1 if best == INF else best
