        INF = float('inf')
        m = len(andValues)
        # f[j]: dict open_and -> min completed cost, where open subarray is index j
        f = [dict() for _ in range(m)]
        for x in nums:
            g = [dict() for _ in range(m)]
            # extend existing open subarrays
            for j in range(m):
                for a, c in f[j].items():
                    v = a & x
                    if g[j].get(v, INF) > c:
                        g[j][v] = c
            # close subarray j-1 at x, open subarray j starting at x
            for j in range(1, m):
                for a, c in f[j - 1].items():
                    if (a & x) == andValues[j - 1]:
                        nc = c + andValues[j - 1]
                        if g[j].get(x, INF) > nc:
                            g[j][x] = nc
            # start subarray 0 at x
            if g[0].get(x, INF) > 0:
                g[0][x] = 0
            f = g
        # answer: subarray m-1 closed at the last element
        best = INF
        for a, c in f[m - 1].items():
            if a == andValues[m - 1]:
                best = min(best, c + andValues[m - 1])
        return -1 if best == INF else best
