class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n = len(nums)
        m = len(andValues)
        INF = float('inf')
        # states[j]: dict open-AND -> min cost of finished subarrays before j-th
        states = [dict() for _ in range(m)]
        result = INF
        for i, x in enumerate(nums):
            new = [dict() for _ in range(m)]
            # continue open subarrays
            for j in range(m):
                for cur, cost in states[j].items():
                    v = cur & x
                    # keep open (only useful if AND can still be andValues[j] or further)
                    d = new[j]
                    if d.get(v, INF) > cost:
                        d[v] = cost
            # close subarray j at x and open j+1 at x
            for j in range(m):
                for cur, cost in states[j].items():
                    if (cur & x) == andValues[j]:
                        c = cost + x
                        if j == m - 1:
                            if i == n - 1:
                                if c < result:
                                    result = c
                        else:
                            d = new[j + 1]
                            if d.get(x, INF) > c:
                                d[x] = c
            # start fresh subarray 0 at x
            d = new[0]
            if d.get(x, INF) > 0:
                d[x] = 0
            states = new
        return result if result != INF else -1

