@st.composite
def gen(draw):
    n = draw(st.integers(1, 7))
    m = draw(st.integers(1, min(n, 4)))
    nums = draw(st.lists(st.integers(1, 15), min_size=n, max_size=n))
    # choose m-1 distinct cut points in 1..n-1 to build a partition
    cuts = sorted(draw(st.lists(st.integers(1, n - 1), min_size=m - 1, max_size=m - 1, unique=True))) if m > 1 else []
    bounds = [0] + cuts + [n]
    andv = []
    for a, b in zip(bounds, bounds[1:]):
        v = nums[a]
        for x in nums[a + 1:b]:
            v &= x
        andv.append(v)
    # sometimes perturb andValues to create infeasible or different cases
    if draw(st.booleans()):
        k = draw(st.integers(0, m - 1))
        andv[k] = draw(st.integers(0, 15))
    return json.dumps(nums) + "\n" + json.dumps(andv) + "\n"


